package org.usbworkbench;
import java.io.*;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;
/** Bounded resumable READ-ERROR ranges. Never writes the drive or remaps physical blocks. */
public final class ReadMap {
 public static final int CHUNK_BLOCKS=2048,MAX_RANGES=4096;
 public interface Cancel {boolean get();}public interface Save {void save(State state)throws IOException;}
 public static final class Range {public final long start,count;Range(long s,long n){start=s;count=n;}}
 public static final class State {
  public final long blocks;public final byte[] identity;public long next,good;public final List<Range> errors=new ArrayList<>();
  State(long b,byte[] id){blocks=b;identity=id.clone();}
  public boolean complete(){return next==blocks;}
  public byte[] encode()throws IOException{validate(this);ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeBytes("UWRDMAP1");out.writeLong(blocks);out.writeLong(next);out.writeLong(good);out.write(identity);out.writeInt(errors.size());for(Range r:errors){out.writeLong(r.start);out.writeLong(r.count);}out.flush();byte[] body=bytes.toByteArray();out.write(sha().digest(body));out.flush();return bytes.toByteArray();}
 }
 private static MessageDigest sha(){try{return MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException e){throw new AssertionError(e);}}
 private static void geometry(BlockDevice d)throws IOException{if(d.blockSize()!=512||d.blockCount()<1||d.blockCount()>4294967296L)throw new IOException("READ_MAP_OPTIONS");}
 public static byte[] identity(BlockDevice d,String deviceKey)throws IOException{geometry(d);if(deviceKey==null||deviceKey.length()>1024)throw new IOException("READ_MAP_OPTIONS");MessageDigest hash=sha();hash.update(deviceKey.getBytes(StandardCharsets.UTF_8));byte[] sector=new byte[512];long blocks=d.blockCount();for(int i=0;i<8;i++){long at=(blocks-1)*i/7;d.read(at,sector,sector.length);hash.update(sector);}return hash.digest();}
 public static State fresh(BlockDevice d,byte[] identity)throws IOException{geometry(d);if(identity==null||identity.length!=32)throw new IOException("READ_MAP_IDENTITY");return new State(d.blockCount(),identity);}
 private static void validate(State s)throws IOException{if(s.blocks<1||s.blocks>4294967296L||s.identity.length!=32||s.next<0||s.next>s.blocks||s.good<0||s.good>s.next||s.errors.size()>MAX_RANGES)throw new IOException("READ_MAP_RECORD");long bad=0,end=0;for(Range r:s.errors){if(r.start<end||r.count<1||r.count>CHUNK_BLOCKS||r.start>s.next||r.count>s.next-r.start)throw new IOException("READ_MAP_RECORD");end=r.start+r.count;bad+=r.count;}if(s.good+bad!=s.next)throw new IOException("READ_MAP_RECORD");}
 public static State decode(InputStream input)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1){if(n<=0||out.size()>MAX_RANGES*16+100-n)throw new IOException("READ_MAP_RECORD");out.write(buffer,0,n);}byte[] all=out.toByteArray();if(all.length<100)throw new IOException("READ_MAP_RECORD");byte[] body=Arrays.copyOf(all,all.length-32);if(!MessageDigest.isEqual(sha().digest(body),Arrays.copyOfRange(all,all.length-32,all.length)))throw new IOException("READ_MAP_RECORD");try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(body))){byte[] magic=new byte[8];in.readFully(magic);if(!Arrays.equals(magic,"UWRDMAP1".getBytes(StandardCharsets.US_ASCII)))throw new IOException("READ_MAP_RECORD");long blocks=in.readLong(),next=in.readLong(),good=in.readLong();byte[] id=new byte[32];in.readFully(id);State s=new State(blocks,id);s.next=next;s.good=good;int count=in.readInt();if(count<0||count>MAX_RANGES||body.length!=68+count*16)throw new IOException("READ_MAP_RECORD");for(int i=0;i<count;i++)s.errors.add(new Range(in.readLong(),in.readLong()));validate(s);return s;}catch(EOFException e){throw new IOException("READ_MAP_RECORD",e);}}
 public static void scan(BlockDevice d,State state,byte[] identity,DiskTools.Progress progress,Cancel cancel,Save save)throws IOException{
  geometry(d);validate(state);if(identity==null||identity.length!=32||d.blockCount()!=state.blocks||!MessageDigest.isEqual(state.identity,identity))throw new IOException("READ_MAP_IDENTITY");byte[] buffer=new byte[CHUNK_BLOCKS*512];long checkpoint=state.next;
  try{while(state.next<state.blocks){if(cancel.get())throw new IOException("CANCELLED");if(state.errors.size()>=MAX_RANGES)throw new IOException("READ_MAP_LIMIT");int count=(int)Math.min(CHUNK_BLOCKS,state.blocks-state.next);long start=state.next;try{d.read(start,buffer,count*512);}catch(IOException e){state.errors.add(new Range(start,count));state.next+=count;throw new IOException("READ_MAP_PAUSED",e);}state.next+=count;state.good+=count;if(state.next-checkpoint>=131072){save.save(state);checkpoint=state.next;}progress.update(state.next,state.blocks);}}finally{save.save(state);}
 }
 public static String report(State s){StringBuilder out=new StringBuilder("READ_MAP\n").append(s.complete()?"1":"0").append('\n').append(s.next).append('\n').append(s.blocks).append('\n').append(s.good).append('\n').append(s.errors.size()).append('\n');int count=0;for(Range r:s.errors){if(count++==100){out.append("...\n");break;}out.append(r.start).append(" + ").append(r.count).append('\n');}return out.toString();}
}
